class CustomDelegate : ReadWriteProperty<Any?, String> {
    private var stored = "default"
    override fun getValue(thisRef: Any?, property: KProperty<*>): String = stored.uppercase()
    override fun setValue(thisRef: Any?, property: KProperty<*>, value: String) { stored = value }
}
class Item { var text: String by CustomDelegate() }
val i = Item()
i.text = "kotlin"
println(i.text)

val mutex = Mutex()
var count = 0
runBlocking {
    withContext(Dispatchers.Default) {
        val jobs = List(1000) {
            launch {
                mutex.withLock { count++ }
            }
        }
        jobs.forEach { it.join() }
    }
}
println(count)

runBlocking {
    val c1 = Channel<String>()
    val c2 = Channel<String>()
    launch { c1.send("First") }
    val res = select<String> {
        c1.onReceive { it }
        c2.onReceive { it }
    }
    println(res)
}

inline fun execute(inlined: () -> Unit, noinline notInlined: () -> Unit): Any {
    inlined()
    return notInlined
}
println(execute({}, { "hello" }) is Function0<*>)

